/* the idiomatic form: no shared mutation, one publish per action */
function reducer(state, action) {
  switch (action.type) {
    case 'TRANSFER': {
      if (state.bal[action.from] < action.amt) return state;   // no-op, not a partial write
      const bal = state.bal.slice();
      bal[action.from] -= action.amt; bal[action.to] += action.amt;
      return { ...state, bal };
    }
    default: return state;
  }
}

/* the real cross-worker form */
const view = new Int32Array(sab);
function cas(i32, expected, next) {
  return Atomics.compareExchange(i32, i32 === view ? 0 : 0, expected, next) === expected;
}
